<?php
namespace App\Controllers\Customer;
use App\Core\Controller;use App\Helpers\CustomerAuth;use App\Services\Midtrans;
class Payments extends Controller {public function create($orderId=null):void{$this->handleCors();if(!$this->isPost())$this->error('Method not allowed',405);$u=CustomerAuth::user();if(!$u)$this->error('Unauthorized',401);$order=$this->db()->query("SELECT * FROM vp_orders WHERE id=? AND customer_id=? AND status='pending_payment' LIMIT 1",[(int)$orderId,(int)$u['id']])->row_array();if(!$order)$this->error('Order not available for payment',404);$customer=$this->db()->query('SELECT * FROM vp_customers WHERE id=? LIMIT 1',[(int)$u['id']])->row_array();try{$snap=Midtrans::snap($order,$customer);$now=$GLOBALS['now']??date('Y-m-d H:i:s');$existing=$this->db()->query('SELECT id FROM vp_payments WHERE order_id=? AND provider=? LIMIT 1',[(int)$order['id'],'midtrans'])->row_array();if($existing)$this->db()->update('vp_payments',['provider_token'=>$snap['token'],'status'=>'pending','updated_at'=>$now],['id'=>(int)$existing['id']]);else $this->db()->insert('vp_payments',['order_id'=>(int)$order['id'],'provider'=>'midtrans','provider_token'=>$snap['token'],'status'=>'pending','gross_amount'=>$order['total'],'created_at'=>$now,'updated_at'=>$now]);$this->success(['token'=>$snap['token'],'redirectUrl'=>$snap['redirect_url']??null,'clientKey'=>(string)(\Env::MIDTRANS_CLIENT_KEY??'')],'Payment created');}catch(\Throwable $e){$this->error($e->getMessage(),422);}}public function status($orderId=null):void{$this->handleCors();$u=CustomerAuth::user();if(!$u)$this->error('Unauthorized',401);$r=$this->db()->query('SELECT o.order_number,o.status order_status,p.status payment_status,p.payment_type,p.paid_at FROM vp_orders o LEFT JOIN vp_payments p ON p.order_id=o.id WHERE o.id=? AND o.customer_id=? LIMIT 1',[(int)$orderId,(int)$u['id']])->row_array();if(!$r)$this->error('Order not found',404);$this->success($r,'Payment status loaded');}}
